#include <bits/stdc++.h>
using namespace std;
typedef long long LL;
typedef pair<int,int> pii;

const int INF = 1e9;
const int MAXN = 15;
const int MAXT = 65;

char a[MAXN][MAXN], b[MAXN][MAXN];
int dist[MAXN][MAXN];
int dir[4][2] = {{-1,0},{1,0},{0,-1},{0,1}};
int id[MAXT][MAXN][MAXN];
int cnt = 1;

struct Edge {
    int u, v;
    LL cap, flow;
    Edge *next, *rev;
    Edge() {}
    Edge(int u, int v, LL cap) : u(u), v(v), cap(cap), flow(0), next(nullptr), rev(nullptr) {}
};

struct Dinic {
    int N;
    vector<Edge*> head;
    vector<int> d, pt;

    Dinic(int N) : N(N), head(N, nullptr), d(N), pt(N) {}

    void add_edge(int u, int v, LL cap) {
        if (u == v) return;
        Edge *e1 = new Edge(u, v, cap);
        Edge *e2 = new Edge(v, u, 0);
        e1->rev = e2;
        e2->rev = e1;
        e1->next = head[u];
        head[u] = e1;
        e2->next = head[v];
        head[v] = e2;
    }

    bool bfs(int S, int T) {
        fill(d.begin(), d.end(), N+1);
        d[S] = 0;
        queue<int> q;
        q.push(S);
        while (!q.empty()) {
            int u = q.front(); q.pop();
            if (u == T) break;
            for (Edge *e = head[u]; e; e = e->next) {
                if (e->flow < e->cap && d[e->v] > d[e->u] + 1) {
                    d[e->v] = d[e->u] + 1;
                    q.push(e->v);
                }
            }
        }
        return d[T] != N+1;
    }

    LL dfs(int u, int T, LL flow = -1) {
        if (u == T || flow == 0) return flow;
        for (int &i = pt[u]; i < N; ++i) {
            Edge *e = head[u];
            for (int j = 0; j < i && e; ++j) e = e->next;
            if (!e) break;
            Edge *oe = e->rev;
            if (d[e->v] == d[e->u] + 1) {
                LL amt = e->cap - e->flow;
                if (flow != -1 && amt > flow) amt = flow;
                LL pushed = dfs(e->v, T, amt);
                if (pushed) {
                    e->flow += pushed;
                    oe->flow -= pushed;
                    return pushed;
                }
            }
        }
        return 0;
    }

    LL max_flow(int S, int T) {
        LL total = 0;
        while (bfs(S, T)) {
            fill(pt.begin(), pt.end(), 0);
            while (LL flow = dfs(S, T))
                total += flow;
        }
        return total;
    }
};

int main() {
    memset(dist, -1, sizeof(dist));
    int n, t;
    scanf("%d%d", &n, &t);
    for (int i = 1; i <= n; ++i) scanf("%s", a[i]+1);
    for (int time = 0; time <= t+1; ++time)
        for (int i = 1; i <= n; ++i)
            for (int j = 1; j <= n; ++j)
                id[time][i][j] = cnt++;
    int source = 0, sink = cnt;
    cnt++;
    for (int i = 1; i <= n; ++i) scanf("%s", b[i]+1);

    // BFS from 'Z'
    deque<pii> dq;
    for (int i = 1; i <= n; ++i)
        for (int j = 1; j <= n; ++j)
            if (a[i][j] == 'Z') {
                dq.emplace_back(i, j);
                dist[i][j] = 0;
            }
    while (!dq.empty()) {
        auto [uy, ux] = dq.front(); dq.pop_front();
        for (int d = 0; d < 4; ++d) {
            int vy = uy + dir[d][0], vx = ux + dir[d][1];
            if (vy >= 1 && vy <= n && vx >= 1 && vx <= n && a[vy][vx] != 'Y' && dist[vy][vx] == -1) {
                dist[vy][vx] = dist[uy][ux] + 1;
                dq.emplace_back(vy, vx);
            }
        }
    }
    for (int i = 1; i <= n; ++i)
        for (int j = 1; j <= n; ++j)
            if (dist[i][j] == -1 || dist[i][j] > t) dist[i][j] = INF;

    Dinic dinic(cnt);
    // source edges
    for (int i = 1; i <= n; ++i)
        for (int j = 1; j <= n; ++j)
            if (a[i][j] >= '1' && a[i][j] <= '9')
                dinic.add_edge(source, id[0][i][j], a[i][j]-'0');

    // time edges (using a single loop over all cells and times)
    for (int i = 1; i <= n; ++i) {
        for (int j = 1; j <= n; ++j) {
            if (a[i][j] == 'Y' || a[i][j] == 'Z') continue;
            for (int d = 0; d < 4; ++d) {
                int vy = i + dir[d][0], vx = j + dir[d][1];
                if (vy >= 1 && vy <= n && vx >= 1 && vx <= n && a[vy][vx] != 'Y' && a[vy][vx] != 'Z') {
                    for (int x = 0; x < t; ++x) {
                        if (dist[vy][vx] >= x+1 && dist[i][j] > x)
                            dinic.add_edge(id[x][i][j], id[x+1][vy][vx], 1000);
                    }
                }
            }
        }
    }

    // sink edges
    for (int i = 1; i <= n; ++i) {
        for (int j = 1; j <= n; ++j) {
            if (a[i][j] == 'Y' || a[i][j] == 'Z') continue;
            if (b[i][j] >= '1' && b[i][j] <= '9') {
                int cap = b[i][j] - '0';
                for (int x = 0; x <= t; ++x)
                    dinic.add_edge(id[x][i][j], id[t+1][i][j], cap);
                dinic.add_edge(id[t+1][i][j], sink, cap);
            }
        }
    }

    printf("%lld\n", dinic.max_flow(source, sink));
    return 0;
}
